/* Auditable neural inference views. All numeric predictions come from Python. */
(function(root){
 'use strict';
 const $=id=>document.getElementById(id),e=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const f=(v,n=3)=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:n});
 const table=(headers,rows)=>'<div class="sequence-matrix"><table><thead><tr>'+headers.map(v=>'<th>'+e(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+e(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const stage=(id,index,title,shape,body)=>`<article id="${id}" class="sequence-stage"><span class="sequence-index">${index}</span><h3>${title}</h3><span class="tensor">${shape}</span>${body}</article>`;
 const chain=items=>'<svg viewBox="0 0 600 105" role="img" aria-label="'+e(items.join(' to '))+'">'+items.map((label,i)=>`<rect x="${i*150+2}" y="15" width="135" height="55" rx="4"/><text x="${i*150+69}" y="47" text-anchor="middle">${e(label)}</text>${i<items.length-1?`<path d="M${i*150+137} 42h15m-5-4 5 4-5 4"/>`:''}`).join('')+'</svg>';
 function detailedGraph(){
  const box=(stage,x,y,w,title,lines)=>`<g tabindex="0" role="button" data-sequence-stage="${stage}" aria-label="${e(title)}"><rect x="${x}" y="${y}" width="${w}" height="${60+lines.length*23}" rx="6"/><text x="${x+18}" y="${y+29}" class="graph-title">${e(title)}</text>${lines.map((line,i)=>`<text x="${x+18}" y="${y+58+i*23}">${e(line)}</text>`).join('')}</g>`;
  const arrow=(d,label,x,y)=>`<path d="${d}" marker-end="url(#sequence-arrow)"/>${label?`<text x="${x}" y="${y}" class="graph-edge">${e(label)}</text>`:''}`;
  return '<section class="detailed-sequence-graph"><h2>CNN–LSTM / complete inference architecture</h2><p>Follow the arrows from inputs to output. Select a block to inspect its explanation below. B = batch size; T = valid time bins. App predictions use B = 1. Labels on wires show the values passed to the next operation.</p><svg viewBox="0 0 1240 1610" role="group" aria-label="Detailed CNN-LSTM architecture with timestep weather, masking, CNN, LSTM, static concatenation, dense head and production calculation"><defs><marker id="sequence-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#c6df9c"/></marker></defs>'+
   box(1,370,20,500,'USER INPUT / SCENARIO',['Map district + season + average temperature','Optional: rain, humidity, wind, radiation','Training: real daily weather instead of template'])+
   arrow('M620 149V182','district + season select reference',640,171)+
   box(1,370,184,500,'TRAINING-ONLY WEATHER REFERENCE',['Local district-season median weather trajectory','Otherwise: nearest-district weather blend','Apply user assumptions; never retrieve target yield'])+
   arrow('M620 313V346','ordered daily/bin values',640,337)+
   box(2,370,348,500,'TIME WINDOW / BINNING / SCALING',['Cutoff = proxy season end minus 60 days','7–13 ten-day bins; 11 values at each timestep','Scale with train-only mean/std; pad to T_max = 13'])+
   arrow('M620 477V511','weather [B,13,11] + lengths [B]',640,502)+
   box(3,370,513,500,'CNN LAYER 1',['Transpose: [B,13,11] → [B,11,13]','Conv1d 11→32; kernel 3; stride 1; padding 1','GELU → apply valid-timestep mask'])+
   arrow('M620 642V676','feature maps [B,32,13]',640,667)+
   box(3,370,678,500,'CNN LAYER 2',['Conv1d 32→32; kernel 3; stride 1; padding 1','GELU → apply valid-timestep mask','Transpose output → ordered [B,13,32]'])+
   arrow('M620 807V841','xₜ: 32 learned local-pattern features',640,832)+
   box(4,370,843,500,'LSTM / HIDDEN SIZE 32',['For t = 1 … valid length: input xₜ, hₜ₋₁, cₜ₋₁','Forget/input/output gates update cₜ and hₜ','Take h_last at valid length; ignore padded tail'])+
   box(5,20,892,305,'STATIC INPUT BRANCH',['District longitude + latitude','Train-standardize coordinates','4 state flags + 5 season flags','Static vector [B,11]'])+
   arrow('M325 1044H345V1090H370','[B,11]',225,1080)+
   arrow('M620 972V1006','final valid hidden [B,32]',640,997)+
   box(5,370,1008,500,'CONCATENATE',['LSTM hidden 32 + static features 11','One fused vector: [B,43]'])+
   arrow('M620 1114V1148','joined [B,43]',640,1139)+
   box(6,370,1150,500,'DENSE REGRESSION HEAD',['Linear 43→64 → GELU → Dropout 0.2','Dropout disabled at inference','Linear 64→1 → standardized yield z [B]'])+
   arrow('M620 1279V1313','z = learned continuous output',640,1304)+
   box(6,370,1315,500,'TARGET INVERSE TRANSFORM',['yield t/ha = z × train_target_std','                       + train_target_mean','No softmax, class label or tree fallback'])+
   box(6,925,1145,295,'USER AREA / PRICE',['Rice-planted hectares','Total land: validation only','Optional selling price ₹/kg'])+
   arrow('M1070 1274V1450','hectares / price',1085,1375)+
   arrow('M620 1444V1475H925','yield t/ha',665,1466)+
   box(6,925,1452,295,'DERIVED HARVEST OUTPUT',['tonnes = yield × rice hectares','kg = tonnes × 1,000','gross value = kg × price'])+
   '<text x="20" y="1578" class="graph-edge">CNN–LSTM learns from measured yields. Template scenarios and neighbouring weather transfer are not validated live forecasts.</text></svg></section>';
 }
 function heatmap(rows,label){
  const max=Math.max(...rows.flat().map(v=>Math.abs(v)),.001),cols=rows[0]?.length||1;
  return '<div class="activation-map"><h4>'+e(label)+'</h4><p>Each square is an actual numerical activation, not an importance score. Hover for its value.</p><div style="grid-template-columns:repeat('+cols+',minmax(8px,1fr))">'+rows.map((row,t)=>row.map((v,c)=>'<span title="row '+(t+1)+', channel '+(c+1)+': '+Number(v).toFixed(6)+'" style="background:'+(v<0?'rgba(215,151,109,':'rgba(184,219,139,')+(.15+.85*Math.abs(v)/max)+')"></span>').join('')).join('')+'</div></div>';
 }
 function attachTrace(r){
  const s=r.sequence,t=r.networkTrace;
  if(!$('seq-stage-2')||!t)return;
  document.querySelectorAll('.last-sequence-run').forEach(el=>el.remove());
  const insert=(id,body)=>$(id).insertAdjacentHTML('beforeend','<details class="last-sequence-run"><summary>Actual latest run · '+e(r.district)+' / '+e(r.season)+'</summary>'+body+'</details>');
  insert('seq-stage-2',table(['t',...s.channels],s.rows.map(row=>[row.step,...row.raw.map(v=>f(v,4))]))+heatmap(s.rows.map(row=>row.scaled),'Standardized weather [T,11]'));
  insert('seq-stage-1',table(['Field','Actual input'],[['District',r.district],['State',r.sourceState],['Season',r.season],['Reference type',r.referenceKind],['Rice hectares',r.areaHa],...Object.entries(r.suppliedWeather)]));
  insert('seq-stage-3',heatmap(s.rows.map(row=>row.scaled),'Convolution layer 1 input [T,11]')+heatmap(t.firstConvolutionFeatures,'Layer 1 output / layer 2 input [T,32]')+heatmap(t.convolutionFeatures,'Layer 2 output / LSTM input [T,32]'));
  insert('seq-stage-4',heatmap(t.lstmStates,'LSTM hidden state at each valid t [T,32]')+table(['Final hidden value','Actual value'],t.lstmStates.at(-1).map((v,i)=>['h_last['+i+']',f(v,6)])));
  insert('seq-stage-5',table(['Static input','Value'],s.staticFeatures.map(v=>[v.name,f(v.value,6)]))+heatmap([t.joined],'Concatenated input to dense layer [1,43]'));
  insert('seq-stage-6',heatmap([t.dense],'GELU output / final linear input [1,64]')+'<p>z = '+f(t.normalizedOutput,6)+'; yield = '+f(t.normalizedOutput,6)+' × '+f(r.networkConfiguration.target_scale,6)+' + '+f(r.networkConfiguration.target_mean,6)+' = '+f(r.yieldTPerHa,6)+' t/ha.</p>');
 }
 function yieldFlow(cfg){
  return '<nav class="sequence-architecture-links" aria-label="Yield stages">'+['Inputs','Weather sequence','Convolution','LSTM','Static branch','Yield output'].map((v,i)=>`<button type="button" data-sequence-stage="${i+1}">${i+1}. ${v}</button>`).join('')+'</nav><div class="sequence-flow">'+
   stage('seq-stage-1','01 / INPUT','Two input branches + output arithmetic','Weather [B,13,11] · static [B,11]',
    '<p><b>Training:</b> real daily NASA weather is joined to measured district-season crop records. Production ÷ harvested area supplies the yield label; neither production nor the label enters the network.</p><p><b>App:</b> map district + season select a training-only weather template. User temperature, rainfall, humidity, wind and radiation modify the template. Blank values remain reference assumptions—not live observations.</p><p>Land and rice-planted area are separate. Rice hectares multiply the final t/ha; total land validates the planted area. The date labels the request, not a learned year input.</p>'+chain(['Daily weather','10-day bins','Scale','Tensor']))+
   stage('seq-stage-2','02 / TIME','Ordered weather input at every timestep','T = 7–13 valid bins · padded to 13',
    '<div class="sequence-rail">'+Array.from({length:13},(_,i)=>'<span>t'+(i+1)+'<br>11 values</span>').join('')+'</div><p>Each t contains Tmax, Tmin, Tavg, vapour pressure, wind, rain, evaporation, radiation, humidity, pressure and bin-day count. Temperature/atmosphere use bin means; rain/evaporation/radiation use totals. Last bins can be shorter than ten days.</p><p>Only weather before the 60-day proxy season-end cutoff is used. Valid lengths exclude padding. Each channel is scaled using training-only mean and standard deviation. No artificial ordering of aggregated CSV columns.</p><code>x[t,c] = (weather[t,c] − train_mean[c]) / train_std[c]</code>')+
   stage('seq-stage-3','03 / LOCAL PATTERNS','Two 1D convolution layers','[B,13,11] → [B,32,13]',
    chain(['11 channels','Conv 11→32','GELU','Conv 32→32'])+'<p>First transpose to [B,11,13]. Kernel size 3 and padding 1 let each layer combine nearby time bins. A second GELU follows the second convolution. The two layers give a five-bin receptive field. Invalid padded positions are masked after each layer.</p><p>The 32 channels are learned representations, not 32 measured weather parameters.</p>')+
   stage('seq-stage-4','04 / TEMPORAL MEMORY','LSTM reads the convolution features','[B,13,32] → final valid hidden [B,32]',
    chain(['t1: 32 values','t2 + memory','… valid t','h_last: 32'])+'<p>At each valid t, the LSTM receives 32 convolution features plus its previous hidden/cell states. Input, forget and output gates update its memory. Training packs valid lengths; deployment gathers the last valid output. Padded timesteps do not determine the final state.</p><details><summary>LSTM update equations</summary><pre>iₜ = sigmoid(Wᵢxₜ + Uᵢhₜ₋₁ + bᵢ)\nfₜ = sigmoid(Wfxₜ + Ufhₜ₋₁ + bf)\ngₜ = tanh(Wgxₜ + Ughₜ₋₁ + bg)\ncₜ = fₜ ⊙ cₜ₋₁ + iₜ ⊙ gₜ\noₜ = sigmoid(Woxₜ + Uohₜ₋₁ + bo)\nhₜ = oₜ ⊙ tanh(cₜ)</pre></details>')+
   stage('seq-stage-5','05 / LOCATION + SEASON','Static inputs join the final LSTM state','32 hidden + 11 static = 43 features',
    chain(['2 coordinates','4 state flags','5 seasons','Join h_last'])+'<p>Longitude and latitude are standardized. State uses four one-hot flags and season five. These 11 static inputs are supplied once per observation—not treated as a weather timestep.</p><p>The target district supplies its own coordinates/state, including when its reference weather is borrowed from neighbours. No district yield, district embedding, crop-year trend or tree prediction is added.</p>')+
   stage('seq-stage-6','06 / REGRESSION','Dense head → yield → harvest','[B,43] → [B,64] → [B,1]',
    chain(['Linear 43→64','GELU','Linear 64→1','Unscale'])+'<p>Dropout 0.2 is used during training and disabled for prediction. The output is a standardized continuous yield, not a disease class or percentage accuracy.</p><code>yield t/ha = z × '+f(cfg.target_scale,6)+' + '+f(cfg.target_mean,6)+'</code><p>Production tonnes = yield × rice hectares. Mass kg = tonnes × 1,000. Optional gross value = kg × entered price. These are arithmetic, not extra model outputs.</p>')+
   '</div><section class="sequence-stage"><h3>Training and evaluation</h3><p>2,642 measured rows: 1,984 train (≤2020), 321 validation (2021–2022), 337 test (2023–2024). AdamW, MSE, batch 64, hidden size 32, early stopping. LSTM, CNN and CNN–LSTM × two seeds were compared by validation RMSE. The chosen CNN–LSTM checkpoint is epoch '+cfg.best_epoch+'.</p><p>Held-out MAE '+f(cfg.test.MAE)+' t/ha · RMSE '+f(cfg.test.RMSE)+' t/ha · R² '+f(cfg.test.R2)+'. These scores use real truncated weather histories. They do not validate template-based current scenarios, unseen districts or individual farms. Trees and MLP are retained only as research artifacts, not active inference.</p></section>';
 }
 function configure(status){
  const cfg=status.yieldConfiguration;
  $('architecture-yield-panel').dataset.neuralArchitecture='true';
  $('architecture-disease-panel').dataset.neuralArchitecture='true';
  $('architecture-yield-panel').innerHTML=detailedGraph()+yieldFlow(cfg);
  $('architecture-yield-panel').querySelectorAll('[data-sequence-stage]').forEach(button=>{
   const choose=()=>{const target=document.getElementById('seq-stage-'+button.dataset.sequenceStage);const data=target.querySelector('.last-sequence-run');if(data)data.open=true;else if(!target.querySelector('.trace-prompt'))target.insertAdjacentHTML('beforeend','<p class="trace-prompt">Run a yield prediction to inspect actual input and output values here. The dimensions above describe the trained network.</p>');target.scrollIntoView({behavior:'smooth',block:'center'});};
   button.addEventListener('click',choose);if(button.tagName.toLowerCase()==='g')button.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();choose();}});
  });
  const image=$('architecture-disease-panel');
  const existing=image.querySelector('.sequence-image-stages');if(existing)existing.remove();
  const imageStages=document.createElement('section');imageStages.className='sequence-image-stages';
  imageStages.innerHTML='<h2>Image tensors at each stage</h2><div class="sequence-flow">'+
   stage('photo-stage-1','01 / FILE','Rice photograph → normalized pixels','Original W×H → [B,3,224,224]',
    '<p>Check JPG/PNG/WebP, size, orientation, blur and lighting. Convert to RGB; resize shorter edge to 256; centre crop 224×224. Pixel/255 then (channel − ImageNet mean)/std. District, season and yield are not image inputs.</p>')+
   stage('photo-stage-2','02 / BACKBONE','EfficientNet-B0 feature maps','3×224² → 32×112² → 320×7²',
    '<p>Stem convolution produces 32 channels. Seven MBConv groups expand/depthwise-convolve, apply squeeze-and-excitation and project features; skip connections apply where shapes permit.</p>'+table(['Stage','Output channels','Spatial size'],[['Stem',32,'112×112'],['MBConv 1',16,'112×112'],['MBConv 2',24,'56×56'],['MBConv 3',40,'28×28'],['MBConv 4',80,'14×14'],['MBConv 5',112,'14×14'],['MBConv 6',192,'7×7'],['MBConv 7',320,'7×7'],['1×1 head',1280,'7×7']]))+
   stage('photo-stage-3','03 / CLASSIFIER','Pooling → ten logits → scores','[B,1280,7,7] → [B,1280] → [B,10]',
    chain(['Global pool','Dropout off','Linear→10','Softmax'])+'<p>Global average pooling reduces each feature map to one value. A trained linear classifier produces ten logits. Softmax pᵢ = exp(zᵢ−max z) / Σ exp(zⱼ−max z). ImageNet initialization is fine-tuned on rice photographs.</p>')+
   stage('photo-stage-4','04 / SCREENING','Candidate label or uncertain result','10 class scores + input-quality flags',
    '<p>The highest-scoring class is the candidate. Score below 65% or quality warnings mark the result uncertain. Scores are not calibrated diagnostic probabilities. No unsupported-disease guarantee and no disease-related yield-loss calculation.</p><p>5,905 training / 1,257 validation / 1,257 held-out images. Test accuracy 85.04%; macro-F1 83.59%. The output flow shows actual logits and scores for the uploaded image.</p>')+'</div>';
  image.replaceChildren(imageStages);
  $('preprocessing-section').innerHTML='<h2>Sequence preprocessing</h2><p>Exact weather joins → seasonal calendar → cutoff 60 days before proxy season end → consecutive ten-day bins → train-only channel scaling → padding with valid lengths. Scale two coordinates; encode state and season. No yield/production input, synthetic target, DAE or tree in the active route.</p><div class="split-strip"><div><b>Train</b><strong>1984</strong><span>2001–2020</span></div><div><b>Validation</b><strong>321</strong><span>2021–2022</span></div><div><b>Test</b><strong>337</strong><span>2023–2024</span></div></div>';
  $('models-section').innerHTML='<h2>Deep-learning models</h2><h3>CNN–LSTM · yield</h3><p>Two temporal convolutions → LSTM → concatenate location and season → dense regression head. Validation-selected checkpoint; test MAE '+f(cfg.test.MAE)+' t/ha, RMSE '+f(cfg.test.RMSE)+' t/ha, R² '+f(cfg.test.R2)+'. Standalone LSTM, 1D CNN and Residual MLP are trained comparisons, not combined predictors.</p><h3>EfficientNet-B0 · image screening</h3><p>Fine-tuned convolutional neural network. Ten rice condition classes; test accuracy 85.04%, macro-F1 83.59%. Photo classification is separate from yield. HistGradientBoosting is an archived benchmark, not an active app model.</p>';
  $('output-section').innerHTML='<h2>Prediction and output</h2><p>Weather sequence + location/season → CNN–LSTM → tonnes/hectare. Multiply by rice-planted area for production. Supplied weather modifies training-only templates; this is a scenario, not a validated live forecast. Show prediction flow displays every timestep, transformed input and output calculation.</p><p>Photograph → EfficientNet-B0 → ten class scores → candidate or uncertain result. Crop health does not adjust the yield estimate.</p>';
  const original=root.CropDesktop.helpText;
  root.CropDesktop.helpText=(button,fallback)=>button.closest('#preprocessing-section,#models-section')?'CNN–LSTM learns from weather sequences plus location and season. EfficientNet-B0 classifies rice images. Both prediction tasks use neural networks.':original(button,fallback);
 }
 function render(request,r){
  const host=$('result');$('empty-result').hidden=true;host.hidden=false;
  const s=r.sequence,max=Math.max(...r.contributions.map(v=>Math.abs(v.contribution)),.001);
  host.innerHTML='<div class="output-grid"><article class="yield-card"><p class="eyebrow">CNN–LSTM / SEASONAL SCENARIO</p><div class="big-number">'+f(r.yieldTPerHa)+' <span>t/ha</span></div><p>'+e(request.district)+' · '+e(r.season)+' · '+e(r.predictionDate)+'</p><div class="output-production"><span>Production</span><b id="seq-production"></b></div></article><article class="explanation-card"><h3>Neural yield estimate</h3><p>'+s.steps+' ordered weather bins + location and season. '+r.referenceCount+' training-season reference records.</p><p>'+e(r.warnings.join(' '))+'</p><button type="button" class="primary" id="analyse-health">Analyse crop health →</button></article></div>'+
   '<section class="metric-controls"><h3>Production scenarios</h3><div class="sequence-result-controls"><label>Rice-planted area (ha)<input id="season-area" type="number" min="0.01" max="1000000" step="0.01" value="'+request.areaHa+'"></label><label>Assumed price (₹/kg)<input id="season-price" type="number" min="0" max="100000" step="0.01" placeholder="Optional"></label></div><p id="seq-calculation" class="sequence-production"></p><div id="seq-area-chart"></div><p>Changing area or price updates arithmetic only. Edit weather inputs to run the network again.</p></section>'+
   '<section class="sequence-stage"><h3>Input sensitivities</h3><p>Prediction minus prediction with one weather channel replaced by its training-bin mean, or one static group replaced by its training reference. Positive means the supplied input raises the result relative to that reference. These are not fixed weights, percentages, additive contributions or causal effects.</p><div class="sequence-effects">'+r.contributions.map(v=>'<div class="sequence-effect" data-negative="'+(v.contribution<0)+'"><div><span>'+e(v.feature)+'</span><b>'+(v.contribution>=0?'+':'')+f(v.contribution)+' t/ha</b></div><div class="sequence-effect-track"><div class="sequence-effect-fill" style="width:'+Math.abs(v.contribution)/max*100+'%"></div></div></div>').join('')+'</div></section>'+
   '<details class="prediction-audit"><summary>Show prediction flow <span>Actual timestep inputs and neural calculation</span></summary><div class="prediction-audit-body"><h3>1. Field and reference inputs</h3>'+table(['Input','Value'],[['District',request.district],['State',r.sourceState],['Season',r.season],['Date',r.predictionDate],['Total land ha',r.landAreaHa],['Rice-planted ha',request.areaHa],...Object.entries(r.suppliedWeather)])+'<p>Reference kind: '+e(r.referenceKind)+'. '+e(r.temperatureMethod)+'</p>'+(r.neighbourDonors.length?table(['Donor district','State','Distance km','Weather blend %'],r.neighbourDonors.map(d=>[d.district,d.state,f(d.distanceKm),f(d.weight*100)])):'')+
   '<h3>2. Actual ordered weather inputs</h3><p>'+s.windowDays+' reference-window days; '+s.leadDays+'-day proxy lead. Days below are relative to season start, not dates of current measured weather. Values are illustrative scenario inputs, not observed symptom or crop progression.</p>'+table(['t','Season days',...s.channels],s.rows.map(row=>[row.step,row.startDay+'–'+row.endDay,...row.raw.map(v=>f(v,4))]))+
   '<details><summary>Standardized sequence tensor [1,'+s.maxSteps+',11]</summary>'+table(['t',...s.channels],s.rows.map(row=>[row.step,...row.scaled.map(v=>f(v,5))]))+'<p>Rows beyond valid length '+s.steps+' are zero padded and masked.</p></details><h3>3. Static branch [1,11]</h3>'+table(['Input','Model value'],s.staticFeatures.map(v=>[v.name,f(v.value,6)]))+
   '<h3>4. Neural computation</h3>'+chain(['Conv 11→32','Conv 32→32','LSTM 32','Join 11 static'])+'<p>Two kernel-3 convolutions + GELU → LSTM last valid hidden state (32 values) + static inputs (11) → Linear(43,64) → GELU → Linear(64,1). Learned weights determine the result; input sensitivities above do not sum to it.</p><code>z = '+f(r.normalizedNetworkOutput,6)+'<br>Yield = z × '+f(r.networkConfiguration.target_scale,6)+' + '+f(r.networkConfiguration.target_mean,6)+' = '+f(r.yieldTPerHa,6)+' t/ha</code><h3>5. Production calculation</h3><p id="seq-flow-production"></p><p>Held-out MAE '+f(r.testMetrics.MAE)+' t/ha; RMSE '+f(r.testMetrics.RMSE)+'; R² '+f(r.testMetrics.R2)+'. Modest district-scale performance; these scores do not validate this scenario or neighbouring district transfer.</p></div></details>';
  function refresh(){const a=$('season-area'),p=$('season-price');if(!a.value||!a.validity.valid)return;const area=Number(a.value),tonnes=r.yieldTPerHa*area,kg=tonnes*1000;let text=f(r.yieldTPerHa,6)+' t/ha × '+f(area)+' ha = '+f(tonnes)+' tonnes = '+f(kg)+' kg';if(p.value&&p.validity.valid)text+=' · gross value ₹'+f(kg*Number(p.value),0);$('seq-calculation').textContent=text;$('seq-flow-production').textContent=text;$('seq-production').textContent=f(tonnes)+' t';$('seq-area-chart').innerHTML='<svg class="result-chart" viewBox="0 0 560 210" role="img" aria-label="Production at half, entered and one and a half times rice area">'+[.5,1,1.5].map((v,i)=>`<rect x="${60+i*170}" y="${160-v*80}" width="100" height="${v*80}" class="demo-bar"/><text x="${110+i*170}" y="${150-v*80}" text-anchor="middle">${f(tonnes*v)} t</text><text x="${110+i*170}" y="190" text-anchor="middle">${f(area*v)} ha</text>`).join('')+'</svg>';}
  $('season-area').addEventListener('input',refresh);$('season-price').addEventListener('input',refresh);refresh();
  $('analyse-health').addEventListener('click',()=>{root.CropHealth.setContext({...request,areaHa:Number($('season-area').value),predictionDate:r.predictionDate});location.hash='health';});
  root.PaddyHelp?.decorate?.();
  attachTrace(r);
 }
 function attachImage(r,url){
  const host=$('architecture-disease-panel');host.querySelector('.image-run-explorer')?.remove();
  if(!r.imageTrace)return;
  const trace=r.imageTrace,explorer=document.createElement('section');explorer.className='image-run-explorer';
  const maps=stage=>'<div class="feature-map-grid">'+stage.maps.map(m=>'<figure><img src="'+m.image+'" alt="Actual activation channel '+m.channel+'"><figcaption>Channel '+m.channel+' · '+f(m.min,4)+' to '+f(m.max,4)+'</figcaption></figure>').join('')+'</div>';
  const stages=[
   {name:'Uploaded photograph',shape:r.width+' × '+r.height,body:()=>'<div class="image-stage-pair"><figure><img src="'+e(url)+'" alt="Uploaded rice photograph"><figcaption>Input: uploaded photograph, orientation corrected.</figcaption></figure><figure><img src="'+trace.crop+'" alt="Actual resized centre crop"><figcaption>Output: RGB centre crop 224 × 224.</figcaption></figure></div><p>Validate format, dimensions, contrast, blur and lighting. This photograph stays local.</p>'},
   {name:'Pixel normalization',shape:'[1,3,224,224]',body:()=>'<img class="trace-crop" src="'+trace.crop+'" alt="Actual model input crop"><p>Input RGB pixels / 255. Output is the normalized channel-first tensor. Mean [0.485,0.456,0.406], std [0.229,0.224,0.225].</p>'+table(['Channel','First 4×4 normalized input values'],trace.normalizedSample.map((row,i)=>[['Red','Green','Blue'][i],row.map(a=>a.map(v=>f(v,4)).join(', ')).join(' / ')]))},
   ...trace.stages.map((stage,i)=>({name:stage.name,shape:'['+stage.inputShape.join(',')+'] → ['+stage.outputShape.join(',')+']',body:()=>'<h4>Actual input to '+e(stage.name)+'</h4>'+(i?maps(trace.stages[i-1]):'<img class="trace-crop" src="'+trace.crop+'" alt="RGB crop corresponding to normalized input"><p>Numerical input is the normalized [1,3,224,224] tensor shown in Pixel normalization.</p>')+'<h4>Actual output features</h4>'+maps(stage)+'<p>'+e(trace.notice)+'</p>'+table(['Output channel 0','Top-left 4×4 actual activations'],[['Values',stage.sample.map(row=>row.map(v=>f(v,5)).join(', ')).join(' / ')]] )})),
   {name:'Global average pooling',shape:'[1,1280,7,7] → [1,1280]',body:()=>maps(trace.stages.at(-1))+'<p>Input: final feature maps. Output: average each channel over its 7×7 spatial grid.</p>'+heatmap(Array.from({length:20},(_,i)=>trace.pooled.slice(i*64,(i+1)*64)),'Actual pooled features: 1,280 values')+'<details><summary>All 1,280 pooled values</summary>'+table(['Feature','Value'],trace.pooled.map((v,i)=>[i,f(v,6)]))+'</details>'},
   {name:'Linear classifier',shape:'[1,1280] → [1,10]',body:()=>'<p>Input: the pooled 1,280-dimensional vector from the previous stage. Dropout is disabled. Learned classifier weights and bias produce these logits.</p>'+table(['Class','Actual output logit'],r.scores.map((v,i)=>[v.label,f(r.logits[i],6)]))},
   {name:'Softmax and output',shape:'10 logits → 10 scores → candidate',body:()=>'<p>Input: actual classifier logits. Subtract max logit, exponentiate, then divide by the sum. Apply the 65% score/quality guard.</p>'+table(['Class','Input logit','Output score'],r.scores.map((v,i)=>[v.label,f(r.logits[i],6),f(v.score*100,3)+'%']))+'<p>Candidate: <b>'+e(r.candidate)+'</b>. Output: '+e(r.uncertain?'uncertain':r.label)+'. Scores are not calibrated diagnostic confidence. No weather or yield input enters this pipeline.</p>'}
  ];
  explorer.innerHTML='<h2>Inspect the latest image prediction</h2><p>Click each stage to view its actual input and output. Feature previews show the first four channels, not lesion masks.</p><div class="image-stage-buttons" role="group" aria-label="Image inference stages">'+stages.map((s,i)=>'<button type="button" data-image-stage="'+i+'">'+(i+1)+'. '+e(s.name)+'</button>').join('')+'</div><article class="sequence-stage image-stage-inspector" aria-live="polite"></article>';
  const choose=i=>{explorer.querySelectorAll('[data-image-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.imageStage)===i)));explorer.querySelector('.image-stage-inspector').innerHTML='<h3>'+e(stages[i].name)+'</h3><span class="tensor">'+e(stages[i].shape)+'</span>'+stages[i].body();};
  explorer.querySelectorAll('[data-image-stage]').forEach(b=>b.addEventListener('click',()=>choose(Number(b.dataset.imageStage))));choose(0);host.prepend(explorer);
 }
 root.SequenceUI={configure,render,yieldFlow,attachImage};
})(window);
